findings.suggestion:
Mirror the createHookedExecutors pattern from billingAgent.js: import { runPreToolCall, runPostToolUse } from '../hooks/index.js' and wrap filteredExecutors before passing them to runAgent. Example:

function createHookedExecutors(executors) {
  const hooked = {};
  for (const [toolName, executorFn] of Object.entries(executors)) {
    hooked[toolName] = async (toolArgs) => {
      const guard = runPreToolCall(toolName, toolArgs);
      if (guard && guard.blocked) return guard.message;
      const rawResult = await executorFn(toolArgs);
      const rawJson = typeof rawResult === 'string' ? rawResult : JSON.stringify(rawResult);
      return runPostToolUse(toolName, rawJson);
    };
  }
  return hooked;
}
const hookedExecutors = createHookedExecutors(filteredExecutors);

Use Promise.allSettled instead of Promise.all so that one agent failure does not cancel the others. Then inspect each result's status field:

const results = await Promise.allSettled(tasks);
taskTypes.forEach((type, idx) => {
  const r = results[idx];
  const value = r.status === 'fulfilled' ? r.value : `[${type} agent error: ${r.reason?.message}]`;
  if (type === 'billing') billingResult = value;
  if (type === 'returns') returnsResult = value;
  if (type === 'technical') technicalResult = value;
});

Remove the customer_context fallback branches. If a specialist context field is empty, pass an empty string or the original userMessage narrowed by role. The triage system prompt already mandates separate context fields; enforce that contract rather than falling back to a shared context:

const billingContext = triage.billing_context || '';
const returnsContext = triage.returns_context || '';
const technicalContext = triage.technical_context || '';

Wrap the blocked response in the same JSON envelope the agent loop expects from tool results. For example:
if (guard && guard.blocked) {
  return JSON.stringify({ blocked: true, message: guard.message });
}

